mapper.select:
select count(*) from p_generation_task t
join p_avatar a on a.id = t.avatar_id and a.account_id = t.account_id
where t.account_id = #{accountId} and t.id = #{taskId}
  and t.source_file_id = #{sourceFileId} and t.official_service_id = #{officialServiceId}
  and a.name = #{name} collate utf8mb4_0900_as_cs and a.visibility = #{visibility}
  and (t.request_hash is null or t.request_hash = #{requestHash})
